async function createOrchestrator() {
    const name = $('#orch-name').value.trim();
    const cwd = $('#orch-cwd').value.trim();
    const model = $('#orch-model').value;
    const profile = 'personal';
    const pipeline = 'default';
    const role = 'orchestrator';
    const errEl = $('#orch-error');
    if (!name || !cwd) { errEl.textContent = T('Name and project path required'); errEl.classList.remove('hidden'); return; }
    const btn = $('#create-orch-btn');
    btn.disabled = true; btn.textContent = T('Creating...'); errEl.classList.add('hidden');
    try {
        await api('/api/sessions', { method: 'POST', body: JSON.stringify({ name, cwd, model, profile, pipeline, role, is_orchestrator: true }) });
        closeModal(); $('#orch-name').value = ''; $('#orch-cwd').value = '';
        currentScope = null;
        await loadOrchestrators();
        selectOrchestrator(name, cwd.replace(/\/+$/, ''));
    } catch (e) { errEl.textContent = e.message; errEl.classList.remove('hidden'); }
    finally { btn.disabled = false; btn.textContent = T('Create Orchestrator'); }
}

async function restartServer() {
    const btn = $('#restart-btn');
    btn.disabled = true; btn.textContent = '⏳';
    try {
        const result = await api('/api/restart', { method: 'POST', timeoutMs: 200000 });
        if (result.journal_loss) {
            Connection.restartAttempt(
                T('Restart will proceed but journal lost: {reason}', {reason: result.journal_loss.reason || T('reason not specified')}),
                true,
            );
        } else {
            const waited = Number(result.waited_s || 0).toFixed(1);
            Connection.restartAttempt(T('Restart prepared in {waited}s', {waited}), false);
        }
    } catch (error) {
        Connection.restartAttempt(T('Restart failed: {error}', {error: error.message || error}), true);
        btn.disabled = false;
        btn.textContent = '⟳';
    }
